import { useReducer, useState } from "react";
import reducer, { initialState } from "./reducer";
import { DEVELOPER, NUMBER, AGE } from "./actionTypes";

import "./App.css";

function App() {
  const [state, dispatch] = useReducer(reducer, initialState);
  const [input, setInput] = useState("");

  function developer() {
    dispatch({ type: DEVELOPER });
  }

  function test(e) {
    e.preventDefault();
    const { field } = e.target;
    setInput(field.value);
  }

  function number(e) {
    e.preventDefault();
    dispatch({ type: NUMBER, payload: input });
    // setInput("");

  }

  function age() {
    dispatch({ type: AGE, payload: input });
    // setInput("");
  }

  return (
    <div className="appContainer">
      <div className="mainApp">
        <div>
          <form className="buttons" onSubmit={test}>
            <div className="fieldDiv">
              <p className="fieldP">Enter Username</p>
              <input className="field" id="field" />
            </div>
            <button className="fieldBtn" type="button" onClick={developer}>
              ADD DEVELOPER
            </button>
            <button className="fieldBtn" type="button">
              SHUFFLE ARRAY
            </button>
            <button className="fieldBtn" type="button" onClick={number}>
              ADD NUMBER
            </button>
            <button className="fieldBtn" type="button">
              REMOVE SINGLE DIGITS
            </button>
            <button className="fieldBtn" type="button">
              CHANGE USER
            </button>
            <button className="fieldBtn" type="submit" onClick={age}>
              ADD AGE
            </button>
          </form>
        </div>
        <div className="output">
          <p>Output</p>
          <p>{JSON.stringify(state)}</p>
          {/* <p>{state}</p> */}
        </div>
      </div>
    </div>
  );
}

export default App;
